export interface InvoiceLine {
  amount: number;
  taxRate?: number;
}

export class InvoiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvoiceError";
  }
}

export function totalWithTax(lines: InvoiceLine[]): number {
  if (lines.length === 0) {
    throw new InvoiceError("Fatura satırı yok");
  }
  return lines.reduce((sum, line) => sum + line.amount * (1 + (line.taxRate ?? 0.2)), 0);
}

export function formatTotal(lines: InvoiceLine[]): string {
  const total = totalWithTax(lines);
  return new Intl.NumberFormat("tr-TR", { style: "currency", currency: "TRY" }).format(total);
}
